package cn.zhuatech.cms.controller; import cn.zhuatech.cms.common.ApiResponse; import cn.zhuatech.cms.dto.CmsDto.*; import cn.zhuatech.cms.service.CmsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('CONTENT_MANAGER','QUALITY','ADMIN')") public class ContentAdminController {private final CmsService service;public ContentAdminController(CmsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<ContentItemView>> orders(){return ApiResponse.ok(service.contentItems());}}
